"""The UAT scenarios - the single source of `UAT-scenarios.md` and `UAT-scenarios.xlsx`.

Edit scenarios HERE, then run `python build_uat.py` (needs `pip install openpyxl`).

Each scenario: (id, role, area, title, steps, expected[, device]).
`steps` and `expected` are lists of short sentences. Labels in "quotes" are the exact words on the
screen. Names in the cast (see CAST) are the people the setup scenarios create.
"""

CAST = [
    # (employee ID, name, role, reports to, designation, used for)
    ("OWN001", "Company Owner", "Owner", "-", "Owner", "created at installation (python -m scripts.seed_owner)"),
    ("UAT-MGR1", "Meera Manager", "Manager", "Owner", "Service Manager", "the manager under test; owns the main branch"),
    ("UAT-MGR2", "Bharat Manager", "Manager", "Owner", "Plant Manager", "the PEER manager: proves one branch cannot see the other"),
    ("UAT-EMP1", "Ravi Engineer", "Employee", "Meera Manager", "Service Engineer", "the main employee under test (work, leave, EOD, punch, service calls)"),
    ("UAT-EMP2", "Sunita Technician", "Employee", "Meera Manager", "Technician", "a second employee in Meera's branch (colleague)"),
    ("UAT-EMP3", "Imran Operator", "Employee", "Bharat Manager", "Machine Operator", "an employee in the OTHER branch"),
]

# Names used by the scenarios for business data created during the run.
DATA = [
    ("Customer", "Acme Forgings (code CU-001), address \"Plot 9, Peenya, Bengaluru\", contact Priya Nair, phone +91 98450 00000"),
    ("Machine", "VMC-850, code MC-001, serial SN-5521, belongs to Acme Forgings"),
    ("Second customer", "Zenith Castings (code CU-002) with machine HMC-500 (MC-002) - created by Bharat Manager"),
    ("Project", "\"Line 3 upgrade\" (created by Meera Manager)"),
    ("Task", "\"Calibrate press line 3\" (assigned to Ravi Engineer)"),
    ("Service call", "SC-2001 \"Spindle vibrates\" (Acme Forgings / VMC-850, urgent, field visit)"),
    ("Files for upload", "one small PNG or JPG photo, one PDF, one .txt, and one file named virus.exe (any content)"),
]

SECTIONS = []  # (title, role, [scenario...])


def section(title, role, rows):
    SECTIONS.append((title, role, rows))


